"account":{"login":"brian-smith-tcril","providerType":"User"},"email":"112954497+brian-smith-tcril@users.noreply.github.com","name":"Brian Smith"},"authoredDate":"2026-08-21T19:04:56Z","committedDate":"2026-08-21T19:04:56Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:24:42.768Z","repositoryId":184327255,"sha":"591d116ba0219f55361c509cf33df49e8390e565"},{"author":{"account":{"login":"brian-smith-tcril","providerType":"User"},"email":"112954497+brian-smith-tcril@users.noreply.github.com","name":"Brian Smith"},"authoredDate":"2026-08-21T18:55:39Z","committedDate":"2026-08-21T18:55:39Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:24:42.768Z","repositoryId":184327255,"sha":"5fe995a9f42da5e9d14b444c4009ec8aac83d2f9"},{"author":{"account":{"login":"brian-smith-tcril","providerType":"User"},"email":"112954497+brian-smith-tcril@users.noreply.github.com","name":"Brian Smith"},"authoredDate":"2026-08-21T18:40:40Z","committedDate":"2026-08-21T18:40:40Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:24:42.768Z","repositoryId":184327255,"sha":"db3808c29377af4a61484940a6248644e38da83c"},{"author":{"account":{"login":"brian-smith-tcril","providerType":"User"},"email":"112954497+brian-smith-tcril@users.noreply.github.com","name":"Brian Smith"},"authoredDate":"2026-08-21T18:34:38Z","committedDate":"2026-08-21T18:34:38Z","committer":{"account":{"login":"web-flow","providerType":"User"},"email":"noreply@github.com","name":"GitHub"},"observedAt":"2026-10-08T17:24:42.768Z","repositoryId":184327255,"sha":"d6d9a6192672cd72feb10326feddfbc73bce60c7"},{"author":{"account":{"login":"brian-smith-tcril","providerType":"User"},"email":"112954497+brian-smith-tcril@users.noreply.github.com","name":"Brian Smith"},"auth